const lessons=[{"sentences":[{"speaker":"A","text":"Hello this is the courier service calling about your scheduled parcel delivery this morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.301375},{"speaker":"A","text":"Unfortunately our driver experienced unexpected traffic delays on the highway near the city center.","position":2,"audioStartSeconds":5.501375,"audioEndSeconds":11.790833333333333},{"speaker":"A","text":"Because of this your package will not arrive during your requested morning time slot.","position":3,"audioStartSeconds":11.990833333333333,"audioEndSeconds":16.990833333333335},{"speaker":"A","text":"We can easily reschedule this delivery for tomorrow afternoon if you are available then.","position":4,"audioStartSeconds":17.190833333333334,"audioEndSeconds":22.603208333333335},{"speaker":"A","text":"Alternatively you can collect the box directly from our downtown depot after five today.","position":5,"audioStartSeconds":22.803208333333334,"audioEndSeconds":28.589291666666668},{"speaker":"A","text":"Please call our customer support team back to confirm your preferred collection choice.","position":6,"audioStartSeconds":28.789291666666667,"audioEndSeconds":34.08566666666667},{"speaker":"A","text":"Thank you for your patience and understanding regarding this temporary shipping delay.","position":7,"audioStartSeconds":34.285666666666664,"audioEndSeconds":39.285666666666664},{"speaker":"A","role":"section-start","text":"Hello this is the local community center manager speaking with an important update.","position":8,"audioStartSeconds":44.285666666666664,"audioEndSeconds":49.324333333333335},{"speaker":"A","text":"We need to inform all members that the main swimming pool is closed today.","position":9,"audioStartSeconds":49.52433333333333,"audioEndSeconds":54.1635},{"speaker":"A","text":"Maintenance workers discovered a minor plumbing issue that requires immediate professional repair work.","position":10,"audioStartSeconds":54.3635,"audioEndSeconds":60.420208333333335},{"speaker":"A","text":"All swimming lessons scheduled for this afternoon have been cancelled until further notice.","position":11,"audioStartSeconds":60.62020833333333,"audioEndSeconds":66.00679166666667},{"speaker":"A","text":"However visitors are welcome to use the indoor fitness gym and tennis courts instead.","position":12,"audioStartSeconds":66.20679166666666,"audioEndSeconds":71.52895833333334},{"speaker":"A","text":"Staff members expect normal pool operations to resume completely by tomorrow morning.","position":13,"audioStartSeconds":71.72895833333334,"audioEndSeconds":77.39908333333334},{"speaker":"A","text":"You can check our official website for further updates before visiting the facility.","position":14,"audioStartSeconds":77.59908333333334,"audioEndSeconds":82.75154166666667}],"questions":[{"prompt":"What caused the parcel delivery delay?","options":["bad weather.","traffic delays.","vehicle trouble."],"answer":"B","evidenceSentence":2,"evidence":"Unfortunately our driver experienced unexpected traffic delays on the highway near the city center.","explanation":"Thông báo đầu tiên nêu rõ tài xế gặp sự cố giao thông trên đường cao tốc."},{"prompt":"When is the earliest alternative time to collect the package from the depot?","options":["after five today.","tomorrow morning.","next Monday."],"answer":"A","evidenceSentence":5,"evidence":"Alternatively you can collect the box directly from our downtown depot after five today.","explanation":"Người gọi đề xuất khách hàng có thể lấy bưu kiện tại kho vào lúc sau năm giờ ngày hôm nay."},{"prompt":"What action does the courier service want the recipient to take?","options":["visit the website.","call support back.","wait for tomorrow."],"answer":"B","evidenceSentence":6,"evidence":"Please call our customer support team back to confirm your preferred collection choice.","explanation":"Người nói yêu cầu khách hàng gọi lại cho đội ngũ hỗ trợ khách hàng để xác nhận lựa chọn."},{"prompt":"Which facility is closed according to the second message?","options":["swimming pool.","fitness gym.","tennis courts."],"answer":"A","evidenceSentence":9,"evidence":"We need to inform all members that the main swimming pool is closed today.","explanation":"Bản tin thứ hai thông báo hồ bơi chính đóng cửa trong ngày hôm nay."},{"prompt":"What alternative area remains open for visitors to use?","options":["outdoor garden.","indoor fitness gym.","conference room."],"answer":"B","evidenceSentence":12,"evidence":"However visitors are welcome to use the indoor fitness gym and tennis courts instead.","explanation":"Khách vẫn có thể sử dụng phòng tập thể dục trong nhà và sân quần vợt."},{"prompt":"When does the manager expect the closed facility to reopen?","options":["tomorrow morning.","next weekend.","later tonight."],"answer":"A","evidenceSentence":13,"evidence":"Staff members expect normal pool operations to resume completely by tomorrow morning.","explanation":"Nhân viên kỳ vọng hồ bơi sẽ hoạt động bình thường trở lại vào sáng ngày mai."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
